rig = dict(id="rigging", part=2, scope="world", title="Rigged Prices, and Banks Too Big to Charge",
 kick="The largest banks fixed the interest rate behind millions of loans and the price of currencies, and paid fines out of profit.",
 sum="A market only works if its prices are honest. Two prices matter more than any others: the interest rate that banks charge each other, which is used to set the rate on mortgages, student loans and business loans around the world, and the exchange rate between currencies. For years both were quietly set to suit the traders of a few very large banks.<br><br>These were not the acts of one rogue employee. Regulators in several countries found the same conduct at bank after bank, carried on for years. Most of the banks involved are on the list of 29 from the last part. This chapter sets out what was done to each price, what it cost the banks, and how prosecutors treated a bank of that size when it broke the criminal law.",
 bridge="The first slide explains the interest rate benchmark called Libor and how banks falsified it. The second shows traders at rival banks agreeing currency prices in a chat room. The third is the case in which prosecutors decided a bank was too large to put on trial.",
 out="Banks were fined more than 9 billion dollars for rigging the rate behind over 300 trillion dollars of loans, five pleaded guilty over currency and interest rates in one day, and a bank that laundered drug money was spared prosecution because of its size. The next chapter looks at the country where the state owns the largest banks.",
 rec="The largest banks rigged the benchmark prices that everyone else's loans depend on, and penalties were paid by the firms and not the people.",
 roles=["Home of banks named in the settlements", "Where the settlements were announced"],
 src=[{"t": "Council on Foreign Relations, Understanding the Libor Scandal", "u": CFR}, {"t": "Reuters in The Christian Science Monitor, Five banks to pay almost 6 billion dollars in fines for rate rigging (20 May 2015)", "u": FX15},
      {"t": "United States Department of Justice, press release of 11 December 2012 on HSBC", "u": "https://www.justice.gov/opa/pr/2012/December/12-crm-1478.html"}],
 steps=[
  st("2005 to 2012", "London", LONDON, 3.0, "The Interest Rate That Banks Made Up",
   "For decades one number sat inside loan contracts all over the world. It was called Libor, the London Interbank Offered Rate. Each morning a panel of large banks reported what it would cost them to borrow from each other, and the average was published. A mortgage or student loan would then be priced as Libor plus a little. According to the Council on Foreign Relations, Libor underpinned more than 300 trillion dollars of loans worldwide. The weakness was that the banks simply stated their figure, and nobody checked it. An international investigation that began in 2012 found that several banks, among them Barclays, UBS, Deutsche Bank, Rabobank and the Royal Bank of Scotland, had reported false figures for years. Traders asked for the number to be nudged so their own bets would pay. During the crash, banks reported low figures to look healthier than they were. Regulators in the United States, Britain and the European Union fined the banks more than 9 billion dollars. Every borrower whose rate was tied to Libor had been paying a price set by the lenders' own traders.",
   CFR, add={"United Kingdom": 0, "Switzerland": 0, "Germany": 0, "Netherlands": 0}, pl=["barclays", "ubs", "deutsche"], ex=["libor"],
   note="Shaded: the home countries of the five banks the source names. Ringed circles: the three of those banks that are on the map's list of 29; Rabobank and the Royal Bank of Scotland are not on that list."),
  st("May 2015", "London, New York and Washington", [-40, 45], 2.0, "The Chat Room Called the Cartel",
   "The same thing was happening to currencies. Chapter 4 explained that the exchange rate sets the cost of imports and the value of wages sent home. Traders at competing banks, who were supposed to be bidding against each other, shared a private chat room that they themselves called the Cartel. There they agreed when to hold back from buying or selling euros and dollars so that each would profit. The United States Department of Justice called it brazenly illegal behaviour carried on almost daily. On 20 May 2015, five banks were fined about 5.7 billion dollars in a single day. Four of them, Barclays, JPMorgan Chase, Citicorp and the Royal Bank of Scotland, pleaded guilty to conspiring to manipulate currency prices. The fifth, UBS, pleaded guilty to rigging interest rates. A guilty plea by a person usually ends a career. These were pleas by companies. The banks kept their licences and their customers, and the fines were paid by the companies.",
   FX15, add={"United Kingdom": 0, "United States": 1, "Switzerland": 0}, arcs=[[LONDON, NY]], an=[["London", "New York"]], pl=["barclays", "jpm", "citi", "ubs", "doj"], ex=["fx2015"],
   note="Shaded: the home countries of the banks that pleaded guilty and the country where the pleas were entered. The Royal Bank of Scotland is named in the source but is not on the map's list of 29."),
  step("megabanks", "Regional Example: The Bank Too Big to Charge"),
 ])
